        if(fn.equals(table_name)){
            return dtname.stringValue();
        }else if(fn.equals(type_name)){
            switch(type){
                case ALL :      return "ALL";
                case FIRST :    return "FIRST";
                case BALANCED : return "BALANCED";
                default :       return "UNDEFINED";
            }
        }
        return fields.get(fn);
    }

