        if (idx < 0) {
          throw new IllegalArgumentException("Should not happen, doesn't contains '['");
        }
        String rawName = name;
        name = name.substring(0, idx);
        arrayIndex = Integer.valueOf(rawName.substring(idx + 1, rawName.length() - 1));
        break;
      case ')':
        idx = name.indexOf("(");
        if (idx < 0) {
