            }
            methodName = func.rename();
          }
        }

        List<Method> methods = methodMap.get(methodName);
        if (methods == null) {
          methods = new ArrayList<>(3);
          methodMap.put(methodName, methods);
        }
        methods.add(method);
      }
    }

    return methodMap;
  }
