    final V lookup (K k) {
        int hc = computeHash (k);
//        return (V) lookuphc (k, hc);
        Object o = lookuphc (k, hc);
        if(o instanceof Some) {
            return ((Some<V>)o).get ();
        } else if(o instanceof None) 
            return null;
        else
            return (V)o;
    }

    final V apply (K k) {
        int hc = computeHash (k);
        Object res = lookuphc (k, hc);
        if (res == null)
            throw new NoSuchElementException ();
        else
            return (V) res;
    }

