        private List<Entry<K, V>> toList (Iterator<Entry<K, V>> it) {
            ArrayList<Entry<K, V>> list = new ArrayList<Map.Entry<K, V>> ();
            while (it.hasNext ()) {
                list.add (it.next ());
            }
