    private Matrix exponentBySqaring(Matrix x, int n,
            Factory factory) {
        if (n<0)
            throw new IllegalArgumentException("The exponent has to be larger than 0.");
        else if (n==0)
            return factory.createIdentityMatrix(rows);
        else if (n>0){
            Matrix result = x;
            while (n>1){
                result = result.multiply(x);
                n--;
            }
            return result;
